// 1. 多级缓存实现
@Service
public class MultiLevelCacheService {
    @Autowired
    private Cache<String, Object> localCache; // Caffeine
    @Autowired
    private StringRedisTemplate redis;
    @Autowired
    private UserMapper userMapper;

    public UserDTO getUser(String userId) {
        // L1: 本地缓存
        UserDTO user = (UserDTO) localCache.getIfPresent(userId);
        if (user != null) return user;

        // L2: Redis缓存
        String json = redis.opsForValue().get("user:" + userId);
        if (json != null) {
            user = JSON.parseObject(json, UserDTO.class);
            localCache.put(userId, user); // 回填L1
            return user;
        }

        // DB
        user = userMapper.selectById(userId);
        if (user != null) {
            redis.opsForValue().set("user:" + userId,
                JSON.toJSONString(user), 30, TimeUnit.MINUTES);
            localCache.put(userId, user);
        }
        return user;
    }
}

// 2. Cache Aside Pattern
@Service
public class CacheAsideService {
    @Transactional
    public void updateUser(String userId, UserUpdateCmd cmd) {
        // 先更新DB
        userMapper.updateById(userId, cmd);
        // 再删除缓存
        redis.delete("user:" + userId);
    }
}

// 3. 延迟双删
@Service
public class DelayDoubleDeleteService {
    @Async
    public void updateUserWithDelayDelete(String userId, UserUpdateCmd cmd) {
        // 第一次删除缓存
        redis.delete("user:" + userId);
        // 更新DB
        userMapper.updateById(userId, cmd);
        // 延迟第二次删除
        CompletableFuture.delayedExecutor(500, TimeUnit.MILLISECONDS)
            .execute(() -> redis.delete("user:" + userId));
    }
}

// 4. 防止缓存击穿 - 互斥锁
public UserDTO getUserWithLock(String userId) {
    String json = redis.opsForValue().get("user:" + userId);
    if (json != null) return JSON.parseObject(json, UserDTO.class);

    // 获取分布式锁
    String lockKey = "lock:user:" + userId;
    boolean locked = redis.opsForValue()
        .setIfAbsent(lockKey, "1", 10, TimeUnit.SECONDS);
    if (locked) {
        try {
            // 双重检查
            json = redis.opsForValue().get("user:" + userId);
            if (json != null) return JSON.parseObject(json, UserDTO.class);

            UserDTO user = userMapper.selectById(userId);
            redis.opsForValue().set("user:" + userId,
                JSON.toJSONString(user), 30, TimeUnit.MINUTES);
            return user;
        } finally {
            redis.delete(lockKey);
        }
    }
    // 未获取锁，短暂等待后重试
    Thread.sleep(50);
    return getUserWithLock(userId);
}

// 5. 防止缓存穿透 - 缓存空值
public UserDTO getUserNullSafe(String userId) {
    String json = redis.opsForValue().get("user:" + userId);
    if ("NULL".equals(json)) return null;
    if (json != null) return JSON.parseObject(json, UserDTO.class);

    UserDTO user = userMapper.selectById(userId);
    if (user == null) {
        // 缓存空值，短过期时间
        redis.opsForValue().set("user:" + userId, "NULL",
            5, TimeUnit.MINUTES);
    } else {
        redis.opsForValue().set("user:" + userId,
            JSON.toJSONString(user), 30, TimeUnit.MINUTES);
    }
    return user;
}
